// Returns true and overwrites hi-res page 1 ($2000-$3FFF) with the castle art
// if (and only if) it currently holds exactly the "ligue o gravador" prompt.
// Safe to call every frame: it's a cheap 8KB compare, and it's a no-op as soon
// as the player presses SPACE and the ROM redraws the screen for real loading.
inline bool overlayKaratekaTitle(byte* ram) {
	if (memcmp(ram + 0x2000, kKaratekaGravadorSignature, 8192) != 0) {
		return false;
	}
	memcpy(ram + 0x2000, kKaratekaCastleBitmap, 8192);
	return true;
}
